CREATE OR REPLACE FUNCTION app_current_tenant() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT NULLIF(current_setting('app.tenant_id',true),'')::uuid $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['tenant_memberships','customers','invoices','stripe_events','recovery_jobs','recovery_logs','communication_log','communication_templates','consent_events'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);EXECUTE format('DROP POLICY IF EXISTS tenant_isolation ON %I',t);EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id=app_current_tenant()) WITH CHECK (tenant_id=app_current_tenant())',t);END LOOP;END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='recovery_app') THEN CREATE ROLE recovery_app NOLOGIN NOSUPERUSER NOBYPASSRLS;END IF;IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='recovery_webhook') THEN CREATE ROLE recovery_webhook NOLOGIN NOSUPERUSER BYPASSRLS;END IF;IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='recovery_worker') THEN CREATE ROLE recovery_worker NOLOGIN NOSUPERUSER BYPASSRLS;END IF;END $$;
GRANT USAGE ON SCHEMA public TO recovery_app,recovery_webhook,recovery_worker;GRANT SELECT,INSERT,UPDATE,DELETE ON tenant_memberships,customers,invoices,recovery_jobs,recovery_logs,communication_log,communication_templates,consent_events TO recovery_app;GRANT SELECT,INSERT,UPDATE ON stripe_events,customers,invoices,recovery_jobs,recovery_logs TO recovery_webhook;GRANT SELECT,INSERT,UPDATE ON customers,invoices,recovery_jobs,recovery_logs,communication_log,communication_templates,consent_events TO recovery_worker;GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA public TO recovery_app,recovery_webhook,recovery_worker;